CREATE DATABASE IF NOT EXISTS student_registration CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE student_registration;
CREATE TABLE IF NOT EXISTS students (id INT PRIMARY KEY AUTO_INCREMENT, full_name VARCHAR(100) NOT NULL, email VARCHAR(120) NOT NULL UNIQUE, phone VARCHAR(15) NOT NULL, gender VARCHAR(20) NOT NULL, course VARCHAR(80) NOT NULL, date_of_birth DATE NOT NULL, address VARCHAR(255) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);